// Example shown in Agents walkthrough: enforce tool allow-list + per-tool timeout
const ALLOWED_TOOLS = new Set(["retrieve", "create_ticket", "lookup_user"]);

export async function runTool(name: string, input: unknown) {
  if (!ALLOWED_TOOLS.has(name)) {
    throw new Error(`tool_not_allowed:${name}`);
  }

  return await withTimeout(5_000, async () => {
    const result = await tools[name](input);
    return validateToolOutput(name, result); // JSON schema validation
  });
}
